<script setup lang="ts">
import {computed} from 'vue';
import {palettes} from '../charts/config';
import type {ChartSettings} from '../state/project';
const props=defineProps<{settings:ChartSettings;headers:string[];combo:boolean}>();
const emit=defineEmits<{change:[value:Partial<ChartSettings>]}>();
const columns=computed(()=>props.headers.slice(1).map((header,index)=>({column:index+1,header})));
const ordered=computed(()=>{const valid=new Set(columns.value.map(item=>item.column)),order=(props.settings.seriesOrder??[]).filter(column=>valid.has(column));for(const item of columns.value)if(!order.includes(item.column))order.push(item.column);return order.map(column=>columns.value.find(item=>item.column===column)!);});
const rightColumns=computed(()=>props.settings.comboRightAxisColumns??columns.value.map(item=>item.column).filter(column=>!(props.settings.comboBarColumns??[1]).includes(column)));
function patchMap<T>(source:Record<string,T>,column:number,value:T,key:keyof ChartSettings){emit('change',{[key]:{...source,[column]:value}} as Partial<ChartSettings>);}
function move(index:number,direction:number){const order=ordered.value.map(item=>item.column),target=index+direction;if(target<0||target>=order.length)return;[order[index],order[target]]=[order[target],order[index]];emit('change',{seriesOrder:order});}
function toggleList(source:number[],column:number,enabled:boolean,key:keyof ChartSettings){const next=new Set(source);enabled?next.add(column):next.delete(column);emit('change',{[key]:[...next].sort((a,b)=>a-b)} as Partial<ChartSettings>);}
function toggleVisible(column:number,visible:boolean){const next=new Set(props.settings.hiddenColumns??[]);visible?next.delete(column):next.add(column);if(next.size>=columns.value.length)return;emit('change',{hiddenColumns:[...next].sort((a,b)=>a-b)});}
function color(index:number){return props.settings.customColors[index]||palettes[props.settings.theme].colors[index%palettes[props.settings.theme].colors.length];}
function setPointStyle(column:number,value:string){patchMap(props.settings.seriesPointStyles,column,value as ChartSettings['seriesPointStyles'][string],'seriesPointStyles');}
function setTrendline(column:number,value:string){patchMap(props.settings.seriesTrendlines,column,value as ChartSettings['seriesTrendlines'][string],'seriesTrendlines');}
function setColor(index:number,value:string){const colors=[...props.settings.customColors];while(colors.length<=index)colors.push(color(colors.length));colors[index]=value;emit('change',{customColors:colors});}
</script>
<template><section class="property-section series-editor"><label>数据系列</label><div v-if="settings.type==='line'||settings.type==='area'||combo" class="trend-options"><label>显示公式<input type="checkbox" :checked="settings.showTrendEquation" @change="emit('change',{showTrendEquation:($event.target as HTMLInputElement).checked})"></label><label>显示 R²<input type="checkbox" :checked="settings.showTrendR2" @change="emit('change',{showTrendR2:($event.target as HTMLInputElement).checked})"></label></div><article v-for="(item,index) in ordered" :key="item.column" class="series-card"><header><input type="color" :value="color(item.column-1)" @input="setColor(item.column-1,($event.target as HTMLInputElement).value)"><input class="series-title" :value="settings.seriesNames[item.column]??item.header" @change="patchMap(settings.seriesNames,item.column,($event.target as HTMLInputElement).value.trim(),'seriesNames')"><button title="上移" :disabled="index===0" @click="move(index,-1)">↑</button><button title="下移" :disabled="index===ordered.length-1" @click="move(index,1)">↓</button><input type="checkbox" title="显示系列" :checked="!settings.hiddenColumns.includes(item.column)" @change="toggleVisible(item.column,($event.target as HTMLInputElement).checked)"></header><div v-if="combo" class="series-options"><select :value="settings.comboBarColumns.includes(item.column)?'bar':'line'" @change="toggleList(settings.comboBarColumns,item.column,($event.target as HTMLSelectElement).value==='bar','comboBarColumns')"><option value="bar">柱状</option><option value="line">折线</option></select><select :value="rightColumns.includes(item.column)?'right':'left'" @change="toggleList(rightColumns,item.column,($event.target as HTMLSelectElement).value==='right','comboRightAxisColumns')"><option value="left">左轴</option><option value="right">右轴</option></select></div><label>透明度 {{Math.round((settings.seriesOpacity[item.column]??1)*100)}}%</label><input type="range" min="0.15" max="1" step="0.05" :value="settings.seriesOpacity[item.column]??1" @input="patchMap(settings.seriesOpacity,item.column,Number(($event.target as HTMLInputElement).value),'seriesOpacity')"><template v-if="settings.type==='line'||settings.type==='area'||(combo&&!settings.comboBarColumns.includes(item.column))"><div class="series-inline"><label>线宽<input type="number" min="1" max="8" :value="settings.seriesLineWidths[item.column]??settings.lineWidth" @change="patchMap(settings.seriesLineWidths,item.column,Number(($event.target as HTMLInputElement).value),'seriesLineWidths')"></label><label>点大小<input type="number" min="0" max="10" :value="settings.seriesPointRadii[item.column]??settings.pointRadius" @change="patchMap(settings.seriesPointRadii,item.column,Number(($event.target as HTMLInputElement).value),'seriesPointRadii')"></label><label class="series-check">虚线<input type="checkbox" :checked="settings.seriesDashed[item.column]??settings.lineDash" @change="patchMap(settings.seriesDashed,item.column,($event.target as HTMLInputElement).checked,'seriesDashed')"></label></div><div class="series-trend"><label>点型<select :value="settings.seriesPointStyles[item.column]??'circle'" @change="setPointStyle(item.column,($event.target as HTMLSelectElement).value)"><option value="circle">圆形</option><option value="rect">方形</option><option value="triangle">三角</option><option value="rectRot">菱形</option><option value="cross">十字</option></select></label><label>趋势线<select :value="settings.seriesTrendlines[item.column]??'none'" @change="setTrendline(item.column,($event.target as HTMLSelectElement).value)"><option value="none">无</option><option value="linear">线性</option><option value="polynomial">二次多项式</option><option value="movingAverage">移动平均</option></select></label><label v-if="settings.seriesTrendlines[item.column]==='movingAverage'">周期<input type="number" min="2" max="20" :value="settings.seriesMovingAveragePeriods[item.column]??3" @change="patchMap(settings.seriesMovingAveragePeriods,item.column,Number(($event.target as HTMLInputElement).value),'seriesMovingAveragePeriods')"></label></div></template></article></section></template>
